tile = [[1]*9 for _ in range(8)]
tile[0][0], tile[0][1] = 7, 9
tile[2][2] = 7
tile[3][5] = 0
out=[]
for r in range(17):
    if r == 8:
        out.append([3]*29)
    else:
        tr = r if r < 8 else r-9
        row=[]
        for c in range(29):
            if c in (9,19): row.append(3)
            else: row.append(tile[tr][c % 10 if c < 9 else (c-10)%10 if c < 19 else (c-20)%10])
        out.append(row)
assert len(out)==17 and all(len(r)==29 for r in out)
import json
print(json.dumps({'action':'submit','grid':out}, separators=(',',':')))
